-- Synthetic metadata fixture, matching the production columns inspected 2026-11-12.
-- Intentionally NOT a replay of the historical migrations or production customer data.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
grant usage on schema public to anon,authenticated,service_role;
create table public.website_admins(user_id uuid primary key);
create table public.website_settings(key text primary key,value jsonb not null default '{}');
create table public.website_sites(
  site_id text primary key,site_name text not null default '',status text not null default 'building',
  current_note text not null default '',
  updated_at timestamptz not null default now(),preview_url text,preview_token_issued_at timestamptz,
  customer_approved boolean not null default false,public_url text,custom_domain text,
  repo_full_name text,publish_branch text not null default 'main',preview_branch text,
  live_path text not null default '/',offline_path text not null default '/docs',
  review_access_token_hash text,preview_access_token_hash text,published_at timestamptz,
  adjustment_free_until timestamptz,update_free_until timestamptz,
  constraint website_sites_status_check check(status in
    ('request_waiting','building','sho_review','customer_review','live','private','improving_private'))
);
create table public.website_orders(
  id uuid primary key default gen_random_uuid(),order_code text not null unique,
  status text not null default 'pending_payment',plan text not null check(plan in ('one','semi','full')),
  site_id text references public.website_sites(site_id),selections jsonb not null default '{}',update_free_until timestamptz,
  customer_access_token_hash text,access_token_created_at timestamptz,template_style text,line_user_id text,
  amount_from integer default 15000,update_plan text default 'none',
  line_display_name text,updated_at timestamptz default now()
);
create table public.website_site_users(site_id text not null references public.website_sites(site_id),
  user_id uuid not null,role text not null check(role in ('owner','editor','viewer')),primary key(site_id,user_id));
create table public.website_jobs(id bigint generated by default as identity primary key,
  site_id text not null references public.website_sites(site_id),kind text not null default 'initial_create',
  status text not null default 'queued',finished_at timestamptz,instruction text,payload jsonb);
create table public.website_review_issues(id bigint generated by default as identity primary key,
  site_id text not null references public.website_sites(site_id),status text not null default 'fixing');
create table public.website_intakes(site_id text primary key references public.website_sites(site_id),payload jsonb not null default '{}');
create table public.website_line_links(site_id text primary key references public.website_sites(site_id),line_user_id text not null unique,line_display_name text);
create table public.website_activity(id bigint generated by default as identity primary key,site_id text not null references public.website_sites(site_id),
  actor_type text not null default 'system',actor_user_id uuid,action text not null,detail text,payload jsonb,created_at timestamptz not null default now());
grant select,insert,update on public.website_admins,public.website_sites,public.website_orders,
  public.website_site_users,public.website_jobs,public.website_review_issues,public.website_intakes,public.website_line_links,public.website_settings,public.website_activity to service_role;
grant usage,select on all sequences in schema public to service_role;
insert into public.website_admins values('11111111-1111-4111-8111-111111111111');
